# Function to verify NuGet package version
function Verify-NuGetPackage {
    param(
        [string]$projectFile,
        [string]$packageId,
        [string]$expectedVersion
    )

    try {
        $content = Get-Content $projectFile
        $pattern = "<PackageReference Include=`"$packageId`" Version=`"([^`"]+)`" />"
        $match = [regex]::Match($content, $pattern)

        if ($match.Success) {
            $currentVersion = $match.Groups[1].Value
            return ($currentVersion -eq $expectedVersion), $currentVersion
        }

        return $false, "Package not found"
    }
    catch {
        return $false, "Error reading project file"
    }
}

