// components/MarkdownEditor.js
'use client' // Required for client-side hooks
import { useState, useEffect } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { Prism as SyntaxHighlighter } from 'prism-react-renderer'

export default function MarkdownEditor({ initialContent = '' }) {
  const [content, setContent] = useState(initialContent)
  const [isPreview, setIsPreview] = useState(false)

  // Tailwind-styled editor
  return (
    <div className="markdown-editor-container">
      <div className="flex mb-4">
        <button 
          onClick={() => setIsPreview(false)}
          className={`px-4 py-2 rounded-l-lg ${!isPreview ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
        >
          Edit
        </button>
        <button 
          onClick={() => setIsPreview(true)}
          className={`px-4 py-2 rounded-r-lg ${isPreview ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
        >
          Preview
        </button>
      </div>

      {isPreview ? (
        <div className="prose max-w-none p-4 border rounded-lg">
          <ReactMarkdown
            remarkPlugins={[remarkGfm]}
            components={{
              code({node, inline, className, children, ...props}) {
                const match = /language-(\w+)/.exec(className || '')
                return !inline && match ? (
                  <SyntaxHighlighter
                    language={match[1]}
                    {...props}
                  >
                    {String(children).replace(/\n$/, '')}
                  </SyntaxHighlighter>
                ) : (
                  <code className={className} {...props}>
                    {children}
                  </code>
                )
              }
            }}
          >
            {content}
          </ReactMarkdown>
        </div>
      ) : (
        <textarea
          className="w-full h-96 p-4 border rounded-lg font-mono"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
      )}
    </div>
  )
}
