// app/documentation/[id]/page.js
'use client'
import { useEffect, useState } from 'react'
import MarkdownEditor from '@/components/MarkdownEditor'
import { loadMarkdownDocument, saveMarkdownDocument } from '@/lib/markdown-handler'

export default function DocumentationPage({ params }) {
  const [content, setContent] = useState('')

  useEffect(() => {
    const loadContent = async () => {
      const loadedContent = await loadMarkdownDocument(params.id)
      setContent(loadedContent)
    }
    loadContent()
  }, [params.id])

  const handleSave = async () => {
    await saveMarkdownDocument({
      id: params.id,
      content
    })
  }

  return (
    <div className="container mx-auto p-4">
      <MarkdownEditor initialContent={content} onChange={setContent} />
      <button 
        onClick={handleSave}
        className="mt-4 bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded"
      >
        Save Document
      </button>
    </div>
  )
}
