```javascript
import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  View,
  StyleSheet,
  PanResponder,
  Dimensions,
  Text,
  Alert,
  ActivityIndicator,
  SafeAreaView,
  TouchableOpacity,
} from 'react-native';
import axios from 'axios';
import { useQuery, useQueryClient } from 'react-query';

// Constants
const SCREEN_WIDTH = Dimensions.get('window').width;
const SCREEN_HEIGHT = Dimensions.get('window').height;
const CANVAS_WIDTH = SCREEN_WIDTH - 40;
const CANVAS_HEIGHT = SCREEN_HEIGHT - 250;
const MAX_COORDINATE = 2160;
const BATCH_SIZE = 10;
const POINT_RADIUS = 10;
const MIN_PATH_LENGTH = 5;
const CONNECTION_TOLERANCE = POINT_RADIUS * 3;

// API Configuration
const API_ENDPOINT = 'https://api.example.com/points'; // Replace with your actual API

// Custom hook for API data fetching with error handling
const usePointsData = () => {
  return useQuery(
    'points',
    async () => {
      try {
        const response = await axios.get(API_ENDPOINT, {
          timeout: 10000, // 10 second timeout
          headers: {
            'Content-Type': 'application/json',
          },
        });

        // Validate response structure
        if (!response.data || !Array.isArray(response.data)) {
          throw new Error('Invalid API response format');
        }

        // Validate each point
        const validatedData = response.data.map((point, index) => {
          if (!point || typeof point !== 'object') {
            throw new Error(`Invalid point at index ${index}`);
          }

          const x = Number(point.x);
          const y = Number(point.y);

          if (isNaN(x) || isNaN(y)) {
            throw new Error(`Invalid coordinates at index ${index}`);
          }

          if (x < 0 || x > MAX_COORDINATE || y < 0 || y > MAX_COORDINATE) {
            throw new Error(`Coordinates out of range at index ${index}`);
          }

          return { x, y, originalIndex: index };
        });

        return validatedData;
      } catch (error) {
        // Generate mock data as fallback
        console.warn('Using mock data due to API error:', error.message);
        return Array.from({ length: 30 }, (_, i) => ({
          x: Math.floor(Math.random() * MAX_COORDINATE),
          y: Math.floor(Math.random() * MAX_COORDINATE),
          originalIndex: i,
        }));
      }
    },
    {
      retry: 2, // Retry failed requests twice
      staleTime: 5 * 60 * 1000, // 5 minutes
      cacheTime: 10 * 60 * 1000, // 10 minutes
    }
  );
};

const App = () => {
  // State management
  const [currentBatchIndex, setCurrentBatchIndex] = useState(0);
  const [userPath, setUserPath] = useState([]);
  const [completedPaths, setCompletedPaths] = useState([]);
  const [isDrawing, setIsDrawing] = useState(false);
  const [validationError, setValidationError] = useState(null);

  // Refs
  const canvasRef = useRef(null);
  const lastPointRef = useRef(null);

  // React Query for API data
  const queryClient = useQueryClient();
  const { data: apiData, isLoading, error, refetch } = usePointsData();

  // Calculate current batch
  const currentBatch = React.useMemo(() => {
    if (!apiData || apiData.length === 0) return [];

    const startIndex = currentBatchIndex * BATCH_SIZE;
    const endIndex = Math.min(startIndex + BATCH_SIZE, apiData.length);

    if (startIndex >= apiData.length) return [];

    return apiData.slice(startIndex, endIndex).map((point, index) => ({
      ...point,
      batchIndex: currentBatchIndex,
      localIndex: index,
      label: startIndex + index + 1,
    }));
  }, [apiData, currentBatchIndex]);

  // Convert API coordinates to screen coordinates
  const convertToScreenCoordinates = useCallback((point) => {
    const padding = 20;
    const availableWidth = CANVAS_WIDTH - 2 * padding;
    const availableHeight = CANVAS_HEIGHT - 2 * padding;

    const screenX = padding + (point.x / MAX_COORDINATE) * availableWidth;
    const screenY = padding + (point.y / MAX_COORDINATE) * availableHeight;

    return {
      x: screenX,
      y: screenY,
      label: point.label,
      originalIndex: point.originalIndex,
    };
  }, []);

  // PanResponder for touch drawing with validation
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt) => {
        if (!currentBatch || currentBatch.length === 0) {
          Alert.alert('No Points', 'No points available to connect.');
          return;
        }

        setIsDrawing(true);
        setValidationError(null);
        const { locationX, locationY } = evt.nativeEvent;

        // Initialize path with first point
        setUserPath([{ x: locationX, y: locationY }]);
        lastPointRef.current = { x: locationX, y: locationY };
      },
      onPanResponderMove: (evt) => {
        if (!isDrawing || !currentBatch || currentBatch.length === 0) return;

        const { locationX, locationY } = evt.nativeEvent;
        const lastPoint = lastPointRef.current;

        // Validate movement (prevent duplicate points)
        if (lastPoint && 
            Math.abs(locationX - lastPoint.x) < 1 && 
            Math.abs(locationY - lastPoint.y) < 1) {
          return;
        }

        setUserPath(prev => [...prev, { x: locationX, y: locationY }]);
        lastPointRef.current = { x: locationX, y: locationY };
      },
      onPanResponderRelease: () => {
        if (!isDrawing) return;

        setIsDrawing(false);
        validateAndCompletePath();
      },
      onPanResponderTerminate: () => {
        setIsDrawing(false);
        setUserPath([]);
        lastPointRef.current = null;
      },
    })
  ).current;

  // Validate if user has connected all points in current batch
  const validateAndCompletePath = () => {
    if (userPath.length < MIN_PATH_LENGTH) {
      setValidationError(`Please draw a longer path. Minimum ${MIN_PATH_LENGTH} points required.`);
      setUserPath([]);
      lastPointRef.current = null;
      return;
    }

    // Calculate if user passed near all points (simplified validation)
    const screenPoints = currentBatch.map(point => convertToScreenCoordinates(point));
    let pointsConnected = 0;

    screenPoints.forEach(screenPoint => {
      // Check if any point in user path is close to this screen point
      const isNear = userPath.some(pathPoint => {
        const distance = Math.sqrt(
          Math.pow(pathPoint.x - screenPoint.x, 2) + 
          Math.pow(pathPoint.y - screenPoint.y, 2)
        );
        return distance < CONNECTION_TOLERANCE; // 3 times point radius as tolerance
      });

      if (isNear) pointsConnected++;
    });

    if (pointsConnected < currentBatch.length * 0.7) { // Require 70% connection
      setValidationError(`Please connect more points. Connected ${pointsConnected} of ${currentBatch.length}.`);
      setUserPath([]);
      lastPointRef.current = null;
      return;
    }

    // Save completed path - THIS IS RETAINED BETWEEN BATCHES
    const completedPath = {
      batchIndex: currentBatchIndex,
      path: [...userPath],
      points: screenPoints,
      timestamp: Date.now(),
    };

    setCompletedPaths(prev => [...prev, completedPath]);
    setUserPath([]);
    lastPointRef.current = null;
    setValidationError(null);

    // Move to next batch - PREVIOUS POINTS WILL BE ERASED
    const nextBatchIndex = currentBatchIndex + 1;
    const totalBatches = Math.ceil(apiData.length / BATCH_SIZE);

    if (nextBatchIndex < totalBatches) {
      setCurrentBatchIndex(nextBatchIndex);
    } else {
      // All batches completed - FINAL POINTS ARE ERASED, ONLY CURVES REMAIN
      Alert.alert(
        'Congratulations!',
        'All points connected! The final curve remains on screen.',
        [
          {
            text: 'Start Over',
            onPress: () => {
              setCurrentBatchIndex(0);
              setCompletedPaths([]);
              queryClient.invalidateQueries('points');
            },
          },
        ]
      );
    }
  };

  // Render points of current batch
  const renderPoints = () => {
    if (!currentBatch || currentBatch.length === 0) return null;

    return currentBatch.map((point) => {
      const screenPoint = convertToScreenCoordinates(point);

      return (
        <View
          key={`point-${point.originalIndex}`}
          style={[
            styles.point,
            {
              left: screenPoint.x - POINT_RADIUS,
              top: screenPoint.y - POINT_RADIUS,
            },
          ]}
        >
          <Text style={styles.pointLabel}>{screenPoint.label}</Text>
        </View>
      );
    });
  };

  // Render user's current drawing path
  const renderUserPath = () => {
    if (userPath.length < 2) return null;

    return userPath.slice(1).map((point, index) => {
      const prevPoint = userPath[index];

      return (
        <View
          key={`user-path-${index}`}
          style={[
            styles.pathSegment,
            {
              left: Math.min(prevPoint.x, point.x),
              top: Math.min(prevPoint.y, point.y),
              width: Math.abs(point.x - prevPoint.x),
              height: Math.abs(point.y - prevPoint.y),
              borderLeftWidth: point.x !== prevPoint.x ? 3 : 0,
              borderTopWidth: point.y !== prevPoint.y ? 3 : 0,
            },
          ]}
        />
      );
    });
  };

  // Render completed paths from previous batches - THESE ARE RETAINED
  const renderCompletedPaths = () => {
    return completedPaths.map((completedPath, pathIndex) => {
      return completedPath.path.slice(1).map((point, segmentIndex) => {
        const prevPoint = completedPath.path[segmentIndex];

        return (
          <View
            key={`completed-${pathIndex}-${segmentIndex}`}
            style={[
              styles.completedPathSegment,
              {
                left: Math.min(prevPoint.x, point.x),
                top: Math.min(prevPoint.y, point.y),
                width: Math.abs(point.x - prevPoint.x),
                height: Math.abs(point.y - prevPoint.y),
                borderLeftWidth: point.x !== prevPoint.x ? 2 : 0,
                borderTopWidth: point.y !== prevPoint.y ? 2 : 0,
              },
            ]}
          />
        );
      });
    });
  };

  // Handle API retry
  const handleRetry = () => {
    refetch();
  };

  // Reset the current drawing
  const handleReset = () => {
    Alert.alert(
      'Reset Drawing',
      'Are you sure you want to reset your current drawing?',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Reset',
          style: 'destructive',
          onPress: () => {
            setUserPath([]);
            lastPointRef.current = null;
            setValidationError(null);
          },
        },
      ]
    );
  };

  // Skip to next batch
  const handleSkipBatch = () => {
    Alert.alert(
      'Skip Batch',
      'Skip to next batch without completing current drawing?',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Skip',
          onPress: () => {
            const nextBatchIndex = currentBatchIndex + 1;
            const totalBatches = Math.ceil(apiData.length / BATCH_SIZE);

            if (nextBatchIndex < totalBatches) {
              setCurrentBatchIndex(nextBatchIndex);
              setUserPath([]);
              setValidationError(null);
            }
          },
        },
      ]
    );
  };

  // Clear the last completed curve
  const handleClearLastCurve = () => {
    if (completedPaths.length === 0) return;

    Alert.alert(
      'Clear Last Curve',
      'Remove the last completed curve?',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Clear',
          onPress: () => {
            const newCompletedPaths = [...completedPaths];
            newCompletedPaths.pop();
            setCompletedPaths(newCompletedPaths);

            // Go back to previous batch if we cleared a curve
            if (currentBatchIndex > 0) {
              setCurrentBatchIndex(prev => prev - 1);
            }
          },
        },
      ]
    );
  };

  // Loading state
  if (isLoading) {
    return (
      <SafeAreaView style={styles.container}>
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color="#2196F3" />
          <Text style={styles.loadingText}>Loading points...</Text>
        </View>
      </SafeAreaView>
    );
  }

  // Error state
  if (error && !apiData) {
    return (
      <SafeAreaView style={styles.container}>
        <View style={styles.errorContainer}>
          <Text style={styles.errorTitle}>Failed to Load Points</Text>
          <Text style={styles.errorMessage}>{error.message}</Text>
          <TouchableOpacity style={styles.retryButton} onPress={handleRetry}>
            <Text style={styles.retryButtonText}>Retry</Text>
          </TouchableOpacity>
          <Text style={styles.fallbackMessage}>
            Using mock data for demonstration
          </Text>
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>Connect the Points</Text>
        <Text style={styles.subtitle}>
          {apiData ? 
            `Batch ${currentBatchIndex + 1} of ${Math.ceil(apiData.length / BATCH_SIZE)}` :
            'Loading...'
          }
        </Text>
      </View>

      <View style={styles.canvasContainer}>
        <View
          ref={canvasRef}
          style={styles.canvas}
          {...panResponder.panHandlers}
        >
          {/* Completed paths (green) - RETAINED BETWEEN BATCHES */}
          {renderCompletedPaths()}

          {/* Current user path (orange) */}
          {renderUserPath()}

          {/* Current batch points - ERASED WHEN MOVING TO NEXT BATCH */}
          {/* Final points automatically erased when all batches completed */}
          {currentBatch.length > 0 && renderPoints()}

          {/* Canvas border */}
          <View style={styles.canvasBorder} />
        </View>

        {validationError && (
          <View style={styles.errorBanner}>
            <Text style={styles.errorBannerText}>{validationError}</Text>
          </View>
        )}
      </View>

      <View style={styles.controls}>
        <Text style={styles.instruction}>
          {currentBatch.length > 0
            ? `Connect points ${currentBatch[0]?.label} to ${currentBatch[currentBatch.length - 1]?.label}`
            : 'All points connected! Final curve remains.'
          }
        </Text>

        <Text style={styles.hint}>
          Draw with your finger to connect the points in order
        </Text>

        <View style={styles.buttonContainer}>
          <TouchableOpacity
            style={[styles.button, styles.resetButton]}
            onPress={handleReset}
            disabled={userPath.length === 0}
          >
            <Text style={styles.buttonText}>Reset Drawing</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.button, styles.skipButton]}
            onPress={handleSkipBatch}
            disabled={!currentBatch || currentBatch.length === 0}
          >
            <Text style={styles.buttonText}>Skip Batch</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.button, styles.clearButton]}
            onPress={handleClearLastCurve}
            disabled={completedPaths.length === 0}
          >
            <Text style={styles.buttonText}>Clear Last Curve</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.button, styles.retryApiButton]}
            onPress={handleRetry}
          >
            <Text style={styles.buttonText}>Refresh Data</Text>
          </TouchableOpacity>
        </View>
      </View>
    </SafeAreaView>
  );
};

